using System.IO;
using System.IO.Path;
using Microsoft.Azure;
using Blobstorage = Microsoft.WindowsAzure.Storage;
using Microsoft.WindowsAzure.Storage.Blob;
using Microsoft.Dynamics.Platform.Integration.SharePoint;
using Microsoft.Dynamics.ApplicationPlatform.Services.Instrumentation;
using Microsoft.DynamicsOnline.Infrastructure.Components.SharedServiceUnitStorage;
using Microsoft.Dynamics.AX.Framework.FileManagement;
/// <summary>
/// CB521_ExciseREgister
/// Class used for NAT3040 reporting
/// </summary>
public class METNature3040ReportController extends SrsReportRunController
{
}

Method.Source:
    /// <summary>
    /// This method is a main method of class
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METNature3040ReportController controller = new METNature3040ReportController();

        if (args.menuItemName() == menuItemActionStr(METNature30Report))
        {
            controller.parmReportName(ssrsReportStr(METNature3040Report, Nature30));
        }
        else if (args.menuItemName() == menuItemActionStr(METNature40Report))
        {
            controller.parmReportName(ssrsReportStr(METNature3040Report, Nature40));
        }

        controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
        controller.parmArgs(args);
        controller.startOperation();
    }

    /// <summary>
    /// Method used to change the behaviour of report if it is in batch
    /// </summary>
    protected void preRunModifyContract()
    {
        //If report is executed in batch then it should create excel file and upload to the sharepoint path
        if (this.isInBatch())
        {
            Filename                                fileName;
            SRSPrintDestinationSettings             settings;
            System.Byte[]                           reportBytes = new System.Byte[0]();
            SRSProxy                                srsProxy;
            SRSReportRunService                     srsReportRunService = new SrsReportRunService();
            Microsoft.Dynamics.AX.Framework.Reporting.Shared.ReportingService.ParameterValue[]  parameterValueArray;
            Map                                     reportParametersMap;
            SRSReportExecutionInfo                  executionInfo = new SRSReportExecutionInfo();
            METNature3040ReportContract             contract = new METNature3040ReportContract();
            METExciseInformationTable               metExciseInformationTable;
            METNAT3040                              metNat3040;

            try
            {
                ttsbegin;
            
                if (args.menuItemName() == menuItemActionStr(METNature30Report))
                {
                    metNat3040 = METNAT3040::NAT30;
                    this.parmReportName(ssrsReportStr(METNature3040Report, Nature30));
                }
                else if (args.menuItemName() == menuItemActionStr(METNature40Report))
                {
                    metNat3040 = METNAT3040::NAT40;
                    this.parmReportName(ssrsReportStr(METNature3040Report, Nature40));
                }

                contract.parmMETNat3040(metNat3040);

                select firstonly Nat3040ReportNumber, RecId from metExciseInformationTable
                    order by Nat3040ReportNumber desc
                    where metExciseInformationTable.NAT3040 == metNat3040    &&
                        metExciseInformationTable.Nat3040ReportNumber != '';

                if (metNat3040 == METNAT3040::NAT30)
                {
                    fileName = strFmt("@MET:Nat30Reportxlsx", metExciseInformationTable.Nat3040ReportNumber);
                    contract.parmNat30Number(metExciseInformationTable.Nat3040ReportNumber);
                }
                else if (metNat3040 == METNAT3040::NAT40)
                {
                    fileName = strFmt("@MET:Nat40Reportxlsx", metExciseInformationTable.Nat3040ReportNumber);
                    contract.parmNat30Number(metExciseInformationTable.Nat3040ReportNumber);
                }

                this.parmReportContract().parmRdpContract(contract);

                settings = this.parmReportContract().parmPrintSettings();
                settings.printMediumType(SRSPrintMediumType::File);
                settings.fileName(fileName);
                settings.fileFormat(SRSReportFileFormat::Excel);

                this.parmReportContract().parmReportServerConfig(SRSConfiguration::getDefaultServerConfiguration());
                this.parmReportContract().parmReportExecutionInfo(executionInfo);

                srsReportRunService.getReportDataContract(this.parmreportcontract().parmReportName());
                srsReportRunService.preRunReport(this.parmreportcontract());

                reportParametersMap = srsReportRunService.createParamMapFromContract(this.parmReportContract());
                parameterValueArray = SrsReportRunUtil::getParameterValueArray(reportParametersMap);
                srsProxy =SRSProxy::constructWithConfiguration(this.parmReportContract().parmReportServerConfig());
                reportBytes = srsproxy.renderReportToByteArray(this.parmreportcontract().parmreportpath(),
                                                parameterValueArray,
                                                settings.fileFormat(),
                                                settings.deviceinfo());

                System.IO.MemoryStream  mstream = new System.IO.MemoryStream(reportBytes);

                mstream.Seek(0, System.IO.SeekOrigin::Begin);

                METSharePointHelper::saveToSharepoint(mstream, fileName, VendParameters::find().METNAT3040DocuTypeId);

                ttscommit;
            }
            catch (Exception::Error)
            {
                throw error("@MET:SharepointError");
            }
        }
        else
        {
            super();
        }
    }

/// <summary>
/// Not to load last user interaction values
/// </summary>
/// <param name = "_loadFromSysLastValue">Boolean reference</param>
/// <returns>Boolean</returns>
public boolean parmLoadFromSysLastValue(boolean _loadFromSysLastValue = loadFromSysLastValue)
{
    return false;
}
